# Hypothesis: a checker should reject instantiating an ABC subclass that leaves an abstract property unimplemented, and should accept isinstance narrowing for a class added with ABC.register.
from abc import ABC, abstractmethod
from typing import assert_type, reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int:
        '''Number of sides.'''

    @abstractmethod
    def area(self) -> float:
        '''Area of the shape.'''

    def describe(self) -> str:
        return f'{self.sides} sides, area {self.area():.1f}'


class Square(Shape):
    def __init__(self, side: float) -> None:
        self._side = side

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self._side * self._side


class Ghost(Shape):
    def area(self) -> float:
        return 0.0


class Triangle:
    sides: int = 3

    def area(self) -> float:
        return 0.5


Shape.register(Triangle)

sq = Square(2.0)
reveal_type(sq.sides)
assert_type(sq.describe(), str)
assert sq.describe() == '4 sides, area 4.0'

try:
    Ghost()  # expect-error
except TypeError:
    ghost_blocked = True
else:
    ghost_blocked = False
assert ghost_blocked

tri = Triangle()
assert isinstance(tri, Shape)
reveal_type(tri.area())
assert tri.area() == 0.5
